{
  "recorte": {
    "id": "AGUA_SRU",
    "foco": "remoção de sulfato, membranas, anti-incrustantes e cloro"
  },
  "material_tecnico": {
    "tema": "URS/dessulfatação: funcionamento, incrustação, inibidores, seleção tecnológica e limites de afirmação",
    "objetivo_didatico": "Consolidar os fundamentos visíveis sobre remoção de sulfato por membranas, seus efeitos sobre risco de incrustação e souring, o papel dos inibidores e os limites práticos e de evidência para seleção e operação.",
    "blocos_base": [
      "AGUA_SRU-V01-B002",
      "AGUA_SRU-V01-B003",
      "AGUA_SRU-V02-B002",
      "AGUA_SRU-V02-B003",
      "AGUA_SRU-V02-B004"
    ],
    "conceitos_centrais": [
      {
        "conceito": "Dessulfatação por membranas",
        "explicacao": "Na URS, a remoção seletiva de sulfato da água de injeção ocorre por nanofiltração sob pressão, em princípio semelhante à osmose inversa."
      },
      {
        "conceito": "Correntes geradas",
        "explicacao": "O processo gera um permeado mais diluído em sulfato, destinado à água de injeção, e um concentrado enriquecido em sulfato, que acumula a carga salina rejeitada."
      },
      {
        "conceito": "Seletividade",
        "explicacao": "A separação decorre da interação entre membrana e solutos. Foi explicitado como conhecimento técnico consolidado que há rejeição preferencial de espécies bivalentes em relação à água, sem universalizar desempenho para toda membrana."
      },
      {
        "conceito": "Incrustação em membranas",
        "explicacao": "A principal limitação reportada para membranas em tratamento de água é a incrustação, que reduz fluxo, pode aumentar passagem de íons e compromete desempenho e vida útil."
      },
      {
        "conceito": "Inibidores de incrustação",
        "explicacao": "Têm caráter essencialmente preventivo e sua estratégia de aplicação depende do ponto onde se deseja prevenir a incrustação."
      },
      {
        "conceito": "Seleção entre URS e alternativas",
        "explicacao": "A decisão depende de estudo de viabilidade técnico-econômica e também de restrições físicas, qualidade/disponibilidade de água e maturidade técnica das alternativas."
      },
      {
        "conceito": "Limites de escopo",
        "explicacao": "Os trechos visíveis não bastam para definir critérios de compatibilidade com cloro, escolha específica de anti-incrustante para membranas, dosagens, janelas de limpeza química ou limites químicos admissíveis de materiais de membrana."
      }
    ],
    "funcionamento_da_urs": {
      "mecanismo_geral": [
        "A alimentação é a água do mar ou outra água de injeção contendo sulfato.",
        "A membrana atua como barreira seletiva, restringindo total ou parcialmente a passagem de íons sulfato.",
        "A separação ocorre sob pressão.",
        "O permeado segue com menor teor de sulfato para uso como água de injeção.",
        "O concentrado retém maior fração dos sais rejeitados e fica mais rico em sulfato."
      ],
      "efeito_operacional_relevante": "A URS permite integrar alta seletividade para íons de interesse ao tratamento de água de injeção.",
      "condicao_preservada": "A semelhança com osmose inversa foi preservada como 'em princípio', evitando equiparação absoluta."
    },
    "incrustacao_e_desempenho": {
      "papel_da_incrustacao": "A incrustação é apresentada como principal limitação do uso de membranas no tratamento de água.",
      "mecanismos_de_perda_de_desempenho": [
        "Deposição de sais pouco solúveis, matéria biológica, orgânicos ou coloides sobre a membrana.",
        "Aumento da resistência hidráulica efetiva.",
        "Redução do fluxo de água através da membrana.",
        "Possível aumento da passagem de íons.",
        "Perda de desempenho e redução da vida útil."
      ],
      "zonas_criticas_na_urs": [
        "Superfícies de membrana.",
        "Regiões associadas ao concentrado.",
        "Trechos do sistema em que o aumento de concentração salina eleva potencial de precipitação."
      ],
      "sintese_importante": "A URS não elimina universalmente o problema de incrustação; ela pode reduzir o risco na água de injeção, mas deslocar ou intensificar risco no concentrado e nas superfícies de membrana.",
      "dependencias_operacionais": [
        "Composição da alimentação.",
        "Grau de concentração/recuperação.",
        "Presença de espécies pouco solúveis.",
        "Condições hidrodinâmicas do módulo."
      ]
    },
    "inibidores_de_incrustacao": {
      "natureza_da_acao": "Preventiva.",
      "mecanismos_descritos": [
        "Adsorção em núcleos ou superfícies ativas do cristal.",
        "Aumento da barreira energética ao crescimento cristalino.",
        "Quando já há cristais formados, efeitos de distorção e dispersão."
      ],
      "fatores_que_afetam_eficiencia": [
        "pH",
        "Compatibilidade com cálcio",
        "Presença de quelantes",
        "Massa molecular",
        "Estabilidade química",
        "Estabilidade térmica"
      ],
      "estrategia_de_aplicacao": {
        "principio": "Deve ser definida após avaliação do potencial de precipitação ao longo do sistema produtivo, do reservatório às facilidades de superfície.",
        "implicacao": "O ponto de risco condiciona o método de proteção."
      },
      "limite_de_alcance": "Inibidores adicionados na água de injeção tendem a adsorver na rocha próxima ao poço injetor e podem não alcançar o poço produtor, restringindo proteção do processo de produção.",
      "aplicacoes_mencionadas": [
        "Squeeze com monitoramento do retorno do inibidor acima da concentração inibitória mínima.",
        "Dosagem em instalações de superfície.",
        "Uso na ausência de unidade de dessulfatação para reduzir incrustação em equipamentos como trocadores de calor e bombas."
      ],
      "regioes_criticas_em_superficie": "Pontos onde ocorre mistura de águas incompatíveis foram destacados como tecnicamente críticos para precipitação."
    },
    "efeitos_sobre_incrustacao_e_souring": {
      "incrustacao_por_sulfato": {
        "efeito": "A água dessulfatada reduz fortemente o potencial de precipitação de sulfatos como BaSO4 e também pode reduzir risco associado a SrSO4 nos trechos citados.",
        "limite": "Isso não implica eliminação de toda incrustação no sistema."
      },
      "incrustacao_por_outros_sais": {
        "efeito": "Mesmo com dessulfatação, a planta pode continuar sujeita a incrustação por outros sais, como CaCO3.",
        "base_campo": "Foi citado exemplo de campo em que a redução de sulfato minimizou BaSO4, mas não impediu incrustação por carbonato de cálcio em unidades de processo."
      },
      "souring": {
        "efeito_potencial": "A dessulfatação pode reduzir a propensão a souring.",
        "limites_preservados": [
          "A resposta não é necessariamente imediata.",
          "A resposta não é necessariamente total.",
          "Sulfato residual ainda pode sustentar atividade de BRS.",
          "O efeito no reservatório pode levar meses ou anos."
        ],
        "restricao_de_evidencia": "Os textos visíveis mencionam proposta/benefício potencial e demora de resposta, sem permitir generalização de desempenho universal em campo para esse objetivo."
      }
    },
    "selecao_tecnologica": {
      "quando_a_urs_tende_a_ser_atrativa": [
        "Quando o risco de incrustação por sulfato de bário e/ou estrôncio é severo.",
        "Quando o tratamento químico recorrente compromete a viabilidade econômica do campo."
      ],
      "criterios_de_decisao": [
        "Investimento inicial da URS.",
        "Custos de operação e manutenção.",
        "Custos das operações de inibição ao longo da vida produtiva.",
        "Perdas associadas a paradas de produção.",
        "Espaço físico necessário para tratar grandes volumes de água.",
        "Restrição de layout, especialmente em plataformas/FPSOs já em operação.",
        "Qualidade e disponibilidade das fontes alternativas de água.",
        "Maturidade técnica da solução alternativa."
      ],
      "alternativas_citadas": [
        "Reinjeção de água produzida, quando houver volume suficiente e após avaliação da qualidade da água.",
        "Injeção de água de aquífero.",
        "Tecnologias com inibidor sólido em nanopartículas dispersas na água de injeção."
      ],
      "cuidado_de_interpretacao": "As alternativas citadas não foram tratadas como substitutas automáticas da URS; sua aplicabilidade depende de condições locais."
    },
    "monitoramento": {
      "principio_geral": "O monitoramento deve verificar se o mecanismo escolhido está protegendo o ponto crítico do sistema.",
      "itens_destacados": [
        "Em squeeze, acompanhar o retorno do inibidor durante a produção para verificar permanência acima da concentração inibitória mínima.",
        "Em estratégias preventivas, confirmar que a proteção está sendo mantida no local crítico.",
        "No caso da dessulfatação, acompanhar desempenho sem assumir que redução de sulfato resolve todos os mecanismos de deposição."
      ]
    },
    "limites_do_que_pode_ser_afirmado_com_base_nos_trechos": [
      "Não há base suficiente aqui para estabelecer dosagens de inibidores.",
      "Não há base suficiente aqui para definir critérios de compatibilidade com cloro.",
      "Não há base suficiente aqui para escolher anti-incrustante específico para membranas.",
      "Não há base suficiente aqui para fixar janelas de limpeza química.",
      "Não há base suficiente aqui para definir limites químicos admissíveis dos materiais de membrana.",
      "Números apagados nos trechos não podem ser reconstruídos."
    ],
    "sintese_integrada": "A URS por nanofiltração é uma estratégia seletiva para reduzir sulfato na água de injeção e, com isso, mitigar risco de incrustações sulfáticas e possivelmente reduzir propensão a souring. Porém, sua operação cria um concentrado mais crítico do ponto de vista de precipitação e não remove automaticamente outros mecanismos de deposição. Por isso, a tecnologia deve ser analisada como parte de um sistema: membranas, concentrado, facilidades de superfície, poços, reservatório e programa químico. Inibidores continuam relevantes, sobretudo como proteção preventiva orientada ao ponto crítico. A seleção entre URS, inibição química e outras fontes de água depende de economia, espaço, qualidade da água e maturidade técnica, sem regra universal única."
  },
  "propostas": [
    {
      "relacao": "Efeito local da mistura de águas incompatíveis sobre a necessidade de dosagem em superfície quando há ou não há URS",
      "recorte_destino": "COMPATIBILIDADE",
      "trechos": [
        "AGUA_SRU-V02-B002",
        "AGUA_SRU-V01-B003"
      ],
      "consultas": [
        "Nos sistemas de superfície citados, em quais pontos ocorre mistura de águas incompatíveis e quais sais predominam no risco local de precipitação?",
        "A presença de URS altera apenas sulfatos ou também muda a criticidade relativa de carbonatos e outros depósitos nesses pontos de mistura?"
      ]
    },
    {
      "relacao": "Monitoramento integrado entre desempenho da URS, retorno de inibidor e persistência de incrustação fora do mecanismo sulfático",
      "recorte_destino": "MONITORAMENTO",
      "trechos": [
        "AGUA_SRU-V02-B004",
        "AGUA_SRU-V01-B003",
        "AGUA_SRU-V02-B002"
      ],
      "consultas": [
        "Quais indicadores locais distinguem perda de desempenho da membrana, proteção efetiva por inibidor e persistência de incrustação por sais não sulfáticos?",
        "Como correlacionar, em campo, redução de sulfato na água de injeção com ocorrência residual de CaCO3 ou outros depósitos em unidades de processo?"
      ]
    }
  ]
}
